preConditionHook:
// A LARGE OPPOSITE TREND BAR FOLLOWED BY A DOJI -- a possible climax and reversal.
// The long side wants the PREVIOUS bar to be a large BEAR trend bar (a bear
// body of at least bodyFraction of its range, and a range of at least
// bigBarMultiple times the ATR) and THIS bar to be a doji. Short is the mirror.
// Under the corpus's standing signal-bar / next-open convention the doji bar is
// the signal bar and the entry is the next open.
//
// KEPT WHOLE rather than split into a trend-bar test, a large-range test and a
// doji test: the first two are evaluated at lag 1 with the direction OPPOSITE
// to the trade, the third at lag 0, and the panes cannot mix lags.
//
// NOT ExhaustionBarAfterLargeTrendBar, which sizes the second bar's body
// against the FIRST BAR'S body and demands a tail on it; this sizes the first
// bar against the ATR and asks only that the second bar be a doji, so the two
// fire on different bars.
//
// The doji test is DojiBar's, unchanged: std::fabs(close - open) measured
// against the bar's OWN range, EL's AbsValue.
//
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: seeded with a full sum on the study's first calculated bar, thereafter
// carrying S += TrueRange - TrueRange[Length], re-seeding when the length
// changes. Same block as AtrProfitTarget, including the TWO separate
// accumulator statements -- EasyLanguage evaluates
// Summation[1] + Price - Price[Length] left to right, and folding it to
// S += in - out rounds differently.
//
// Products, not quotients: EasyLanguage raises a runtime divide-by-zero and a
// zero-range bar is legal data.
//
// Deepest bar touched: atrLookback + 1.
if (atrLenState != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLenState = (int)atrLookback;
} else {
    const int out = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrValue = atrSum / (int)atrLookback;
